11	/// Resolve a JSON argument: if it's literally "-", read stdin to a String.
12	/// Otherwise return the argument as-is.
13	fn read_json_arg(arg: &str) -> Result<String> {
14	    if arg == "-" {
15	        let mut buf = String::new();
16	        std::io::stdin()
17	            .read_to_string(&mut buf)
18	            .context("reading JSON from stdin")?;
19	        if buf.trim().is_empty() {
20	            bail!("stdin was empty — expected JSON payload");
21	        }
22	        Ok(buf)
23	    } else {
24	        Ok(arg.to_string())
25	    }
26	}
