539	/// Write the TOML document and (unless suppressed) also write the `<file>.sha256`
540	/// sidecar. The sidecar is hashed from the bytes that actually landed on disk
541	/// after the atomic rename, so the digest always reflects the serialiser's
542	/// output. Failure to write the sidecar is reported as a stderr warning but
543	/// does not fail the outer write — the primary data is already durable.
544	fn write_toml_with_sidecar(
545	    path: &Path,
546	    value: &TomlValue,
547	    integrity: IntegrityOpts,
548	) -> Result<()> {
549	    write_toml(path, value)?;
550	    if integrity.write_sidecar
551	        && let Err(e) = write_integrity_sidecar(path)
552	    {
553	        eprintln!(
554	            "tomlctl: warning: wrote {} but failed to refresh integrity sidecar: {:#}",
555	            path.display(),
556	            e
557	        );
558	    }
559	    Ok(())
560	}
