577	/// Return the canonical sidecar path for `file`: `<file>.sha256`.
578	fn sidecar_path(file: &Path) -> PathBuf {
579	    let mut s = file.as_os_str().to_os_string();
580	    s.push(".sha256");
581	    PathBuf::from(s)
582	}
