595	/// Compute the SHA-256 hex digest of a file's current bytes.
596	fn sha256_hex_of_file(file: &Path) -> Result<String> {
597	    let bytes =
598	        fs::read(file).with_context(|| format!("reading {} for hashing", file.display()))?;
599	    Ok(hex_lower(&Sha256::digest(&bytes)))
