634	/// If `--verify-integrity` was set, verify the target against its sidecar.
635	/// Errors if the sidecar is missing or the digest disagrees.
636	fn maybe_verify_integrity(file: &Path, integrity: IntegrityOpts) -> Result<()> {
637	    if !integrity.verify_on_read {
638	        return Ok(());
639	    }
640	    verify_integrity(file)
641	}
