643	fn verify_integrity(file: &Path) -> Result<()> {
644	    let sidecar = sidecar_path(file);
645	    if !sidecar.exists() {
646	        bail!(
647	            "integrity check failed: sidecar {} is missing (expected `<hex>  <basename>` format — rewrite the file without --no-write-integrity to regenerate)",
648	            sidecar.display()
649	        );
650	    }
651	    let sidecar_text = fs::read_to_string(&sidecar)
652	        .with_context(|| format!("reading sidecar {}", sidecar.display()))?;
653	    let expected = sidecar_text.split_whitespace().next().ok_or_else(|| {
654	        anyhow!(
655	            "integrity sidecar {} is empty or malformed",
656	            sidecar.display()
657	        )
658	    })?;
659	    if expected.len() != 64 || !expected.chars().all(|c| c.is_ascii_hexdigit()) {
660	        bail!(
661	            "integrity sidecar {} does not contain a 64-hex-char digest (got `{}`)",
662	            sidecar.display(),
663	            expected
664	        );
665	    }
666	    let actual = sha256_hex_of_file(file)?;
667	    if !expected.eq_ignore_ascii_case(&actual) {
668	        bail!(
669	            "integrity check failed for {}: expected {}, actual {} (sidecar: {})",
670	            file.display(),
671	            expected,
672	            actual,
673	            sidecar.display()
674	        );
675	    }
676	    Ok(())
677	}
