768	fn toml_to_json(v: &TomlValue) -> JsonValue {
769	    match v {
770	        TomlValue::String(s) => JsonValue::String(s.clone()),
771	        TomlValue::Integer(i) => JsonValue::from(*i),
772	        TomlValue::Float(f) => serde_json::Number::from_f64(*f)
773	            .map(JsonValue::Number)
774	            .unwrap_or(JsonValue::Null),
775	        TomlValue::Boolean(b) => JsonValue::Bool(*b),
776	        TomlValue::Datetime(dt) => JsonValue::String(dt.to_string()),
777	        TomlValue::Array(a) => JsonValue::Array(a.iter().map(toml_to_json).collect()),
778	        TomlValue::Table(t) => {
779	            let mut m = serde_json::Map::new();
780	            for (k, v) in t.iter() {
781	                m.insert(k.clone(), toml_to_json(v));
782	            }
783	            JsonValue::Object(m)
784	        }
785	    }
786	}
