788	fn json_to_toml(v: &JsonValue) -> Result<TomlValue> {
789	    match v {
790	        JsonValue::Null => bail!("TOML has no null type"),
791	        JsonValue::Bool(b) => Ok(TomlValue::Boolean(*b)),
792	        JsonValue::Number(n) => {
793	            if let Some(i) = n.as_i64() {
794	                Ok(TomlValue::Integer(i))
795	            } else if let Some(f) = n.as_f64() {
796	                Ok(TomlValue::Float(f))
797	            } else {
798	                bail!("number `{}` is not representable in TOML", n)
799	            }
800	        }
801	        JsonValue::String(s) => Ok(TomlValue::String(s.clone())),
802	        JsonValue::Array(a) => {
803	            let items: Result<Vec<_>> = a.iter().map(json_to_toml).collect();
804	            Ok(TomlValue::Array(items?))
805	        }
806	        JsonValue::Object(m) => {
807	            let mut t = toml::Table::new();
808	            for (k, v) in m.iter() {
809	                t.insert(k.clone(), json_to_toml(v)?);
810	            }
811	            Ok(TomlValue::Table(t))
812	        }
813	    }
814	}
