946	fn items_update_value(
947	    doc: &mut TomlValue,
948	    id: &str,
949	    patch: &JsonValue,
950	    unset: &[String],
951	) -> Result<()> {
952	    let patch_obj = patch
953	        .as_object()
954	        .ok_or_else(|| anyhow!("--json must be a JSON object"))?;
955	
956	    let arr = items_array_mut(doc)?;
957	    for item in arr.iter_mut() {
958	        let tbl = match item.as_table_mut() {
959	            Some(t) => t,
960	            None => continue,
961	        };
962	        let matches = tbl.get("id").and_then(|v| v.as_str()) == Some(id);
963	        if !matches {
964	            continue;
965	        }
966	        for (k, v) in patch_obj.iter() {
967	            tbl.insert(k.clone(), maybe_date_coerce(k, v)?);
968	        }
969	        for key in unset {
970	            tbl.remove(key);
971	        }
972	        return Ok(());
973	    }
974	    bail!("no item with id = {}", id)
975	}
