1078	fn items_find_duplicates(doc: &TomlValue, tier: DupTier) -> Result<Vec<JsonValue>> {
1079	    let items = match items_array(doc) {
1080	        Ok(a) => a.clone(),
1081	        Err(_) => return Ok(Vec::new()),
1082	    };
