1090	fn dup_group_json(tier: &str, key: &str, items: &[&TomlValue]) -> JsonValue {
1091	    let mut obj = serde_json::Map::new();
1092	    obj.insert("tier".into(), JsonValue::String(tier.into()));
1093	    obj.insert("key".into(), JsonValue::String(key.into()));
1094	    obj.insert(
1095	        "items".into(),
1096	        JsonValue::Array(items.iter().map(|v| toml_to_json(v)).collect()),
1097	    );
1098	    JsonValue::Object(obj)
1099	}
