1825	    #[test]
1826	    fn write_integrity_sidecar_roundtrip() {
1827	        let dir = tempfile::tempdir().unwrap();
1828	        let target = dir.path().join("ledger.toml");
1829	        let mut doc = led();
1830	        items_add(
1831	            &mut doc,
1832	            r#"{"id":"R5","file":"src/c.rs","line":1,"severity":"suggestion","effort":"trivial","category":"quality","summary":"baz","first_flagged":"2026-04-17","rounds":1,"status":"open"}"#,
1833	        )
1834	        .unwrap();
1835	        write_toml_with_sidecar(&target, &doc, integrity_write_only()).unwrap();
1836	
1837	        // Sidecar exists with sha256sum-style format.
1838	        let sidecar = sidecar_path(&target);
1839	        assert!(sidecar.exists(), "sidecar must be written by default");
1840	        let side = fs::read_to_string(&sidecar).unwrap();
1841	        assert!(side.ends_with("  ledger.toml\n"), "got sidecar: {side:?}");
1842	        let hex = side.split_whitespace().next().unwrap();
1843	        assert_eq!(hex.len(), 64);
1844	
1845	        // Verify succeeds.
1846	        verify_integrity(&target).unwrap();
1847	
1848	        // Flip a byte in the target; verify now errors with both digests.
1849	        let mut bytes = fs::read(&target).unwrap();
1850	        // Mutate a byte in a way that keeps the file valid TOML — replace the
1851	        // first 'R' in the item ids with 'Q'. Actually we just need any change
1852	        // for the hash to differ; integrity check doesn't reparse.
1853	        let pos = bytes.iter().position(|&b| b == b'R').unwrap();
1854	        bytes[pos] = b'Q';
1855	        fs::write(&target, &bytes).unwrap();
1856	        let err = verify_integrity(&target).unwrap_err();
1857	        let msg = format!("{err:#}");
1858	        assert!(
1859	            msg.contains("expected") && msg.contains("actual"),
1860	            "expected dual-digest message, got: {msg}"
1861	        );
1862	    }
